// ============================================
// VALIDATION INPUT - LLM URL Extractor
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required field ---
let url = body.url || ctx.url || '';
 if (!url && (body.urls || ctx.urls)) {
    const urls = body.urls || ctx.urls;
    url = Array.isArray(urls) ? urls[0] : urls;
  }

// Ensure url is a string
if (typeof url !== 'string') {
  url = String(url || '');
}

if (!url || url.trim().length === 0) {
  errors.push('url requis (chaine non vide)');
} else {
  // Validate URL format using regex (more reliable in n8n environment)
  const urlPattern = /^https?:\/\/[^\s/$.?#].[^\s]*$/i;
  if (!urlPattern.test(url.trim())) {
    errors.push('url invalide (format URL requis, ex: https://example.com)');
  }
}

// --- Optional context fields for tracing (no validation errors if missing) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
//const userRequest = body.user_request || ctx.user_request || null;

// --- Optional parameters ---
// --- Provider normalization ---
let provider = (body.provider || ctx.provider || 'anthropic').toLowerCase();
// Accept 'claude' as alias for 'anthropic'
if (provider === 'claude') {
  provider = 'anthropic';
}

//const provider = (body.provider || ctx.provider || 'anthropic').toLowerCase();
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 2048);
//const extractionSchema = body.extraction_schema || ctx.extraction_schema || null;

// --- Extraction schema (support both names) ---
const extractionSchema = body.extraction_schema || body.output_schema || ctx.extraction_schema || ctx.output_schema || null;

// --- User request (support 'query' as alias) ---
const userRequest = body.user_request || body.query || ctx.user_request || ctx.query || null;


// Validate provider
const validProviders = ['anthropic', 'openai'];
if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider} (doit etre: ${validProviders.join(', ')})`);
}

// --- API Keys from env or request ---
const anthropicKey = body.anthropic_api_key || body.plugin_context?.api_keys?.anthropic || $env.ANTHROPIC_API_KEY || '';
const openaiKey = body.openai_api_key || body.plugin_context?.api_keys?.openai || $env.OPENAI_API_KEY || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  url: url.trim(),
  provider: provider,
  max_tokens: maxTokens,
  extraction_schema: extractionSchema,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  anthropicKey: anthropicKey,
  openaiKey: openaiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// EXTRACT CONTENT FROM HTML
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Check for fetch errors
if (input.error || (input.statusCode && input.statusCode >= 400)) {
  return {
    success: false,
    fetchError: true,
    errorMessage: input.error?.message || `HTTP ${input.statusCode} error`,
    statusCode: input.statusCode || 500,
    ...prevData
  };
}

// Get HTML from response - handle both fullResponse and direct response
let html = '';
if (typeof input === 'string') {
  html = input;
} else if (input.body) {
  html = typeof input.body === 'string' ? input.body : JSON.stringify(input.body);
} else if (input.data) {
  html = typeof input.data === 'string' ? input.data : JSON.stringify(input.data);
}

// Simple content extraction
function extractContent(html) {
  if (!html) return { title: '', content: '', excerpt: '' };

  // Remove scripts, styles, comments
  let clean = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '');

  // Extract title
  const titleMatch = clean.match(/<title[^>]*>([^<]*)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : '';

  // Try to find main content in order of specificity
  let content = '';
  const articleMatch = clean.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
  const mainMatch = clean.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
  const divContentMatch = clean.match(/<div[^>]*(?:id|class)=["'][^"']*content[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);

  if (articleMatch) {
    content = articleMatch[1];
  } else if (mainMatch) {
    content = mainMatch[1];
  } else if (divContentMatch) {
    content = divContentMatch[1];
  } else {
    const bodyMatch = clean.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    content = bodyMatch ? bodyMatch[1] : clean;
  }

  // Remove HTML tags and clean up
  const textContent = content
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();

  return {
    title: title,
    content: textContent,
    excerpt: textContent.substring(0, 500) + (textContent.length > 500 ? '...' : '')
  };
}

const extracted = extractContent(html);

return {
  ...prevData,
  fetchError: false,
  pageTitle: extracted.title,
  pageContent: extracted.content,
  pageExcerpt: extracted.excerpt,
  contentLength: extracted.content.length,
  rawHtmlLength: html.length,
  finalUrl: input.headers?.location || prevData.url
};

// ============================================
// BUILD FETCH ERROR
// ============================================

const input = $input.first().json;
const startTime = input.startTime || Date.now();

return {
  success: false,
  _trace: {
    service_response: { 
      fetch_error: input.errorMessage,
      status_code: input.statusCode
    },
    provider: 'none',
    mode: 'error',
    latency_ms: Date.now() - startTime,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'FETCH_ERROR',
    message: input.errorMessage,
    http_status: 502
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
