  guild_id: guildId,
  user_request: userRequest,
  _trace: _trace
};

// ============================================
// FORMAT ANTHROPIC RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Extract Content').first().json;
const startTime = prevData.startTime || Date.now();

const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Handle error response
if (input.error || input.type === 'error') {
  return {
    success: false,
    error: {
      code: 'LLM_ERROR',
      message: input.error?.message || 'Anthropic API error',
      http_status: 500
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'anthropic',
      model: 'claude-sonnet-4-20250514',
      tokens: { input: 0, output: 0 },
      latency_ms: Date.now() - startTime,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  };
}

const rawResponse = input.content?.[0]?.text || '{}';
let extractedData = {};
try {
  extractedData = JSON.parse(rawResponse);
} catch (e) {
  extractedData = { raw_text: rawResponse };
}

const _trace = {
  llm_response: extractedData,
  service_response: input,
  provider: 'anthropic',
  model: input.model || 'claude-sonnet-4-20250514',
  tokens: {
    input: input.usage?.input_tokens || 0,
    output: input.usage?.output_tokens || 0
  },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return {
  success: true,
  data: {
    extracted_data: extractedData,
    source_url: prevData.url,
    page_title: prevData.pageTitle,
    content_length: prevData.contentLength
  },
  meta: {
    provider: 'anthropic',
    model: input.model || 'claude-sonnet-4-20250514'
  },
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  _trace: _trace
};
